
import React, { useEffect, useMemo, useState } from "react";

import { Image } from "react-bootstrap";
import useDroppableArea from "../../hooks/useDroppableArea";
import ReusableTable from "../../components/Table/Table";
import { getTableData,tableColumns} from "./dataHelpers";

const CloneRouteTemplate = () => {

  const [tableKey, setTableKey] = useState(0);
  const [tableData, setTableData] = useState([]);
  const { isDropped, handleDrop } = useDroppableArea();
  const [routeTemplate, setRouteTemplate] = useState([]);
  const columns = useMemo(() => tableColumns, []);
    // Update table data when droppedObjectData changes
    const newTableData = useMemo(
      () => getTableData(routeTemplate),
      [routeTemplate]
    );
  return (    
    
    

    <div className={`droppable-container mt-4 ${isDropped ? "dropped-active" : ""}`}>
    <Image style={{ width: "90px", height: "90px" }} src="./images/drag.png" alt="Data Collect" className="search-icon" />
    <span className="drag-and-drop-text">Drag and Drop</span>
   
    <>
              <div className="wrapper-cta">
               
                <ReusableTable
                  key={tableKey}
                  data={tableData}
                  columns={columns}                
                />
              </div>
            </>
   
  </div>


                 
  );
};

export default CloneRouteTemplate;
