
export const getTableData = (droppedObjectData) => {
  if (!droppedObjectData) {    return [];  }

  const item = droppedObjectData.draggedData;

  return item.map((routeTemplate) => {
    let rowData = {      
      Title: routeTemplate.Title || "N/A",
      Description: routeTemplate.Description || "N/A",
      Type: routeTemplate.Type || "N/A",
      Revision: routeTemplate["Dropped Revision"] || "N/A",
      State: routeTemplate["Maturity State"] || "N/A",
      Owner: routeTemplate.Owner || "N/A",    
      Collabspace: routeTemplate["Collaborative Space Title"] || "N/A",
    };
    
    return rowData;
  });
};

export const tableColumns = [
  {
    accessorKey: "Title",
    header: "Title",
    columnPinning: true,
  },
  { accessorKey: "Title", header: "Title" },
  { accessorKey: "Description", header: "Description" },
  { accessorKey: "Type", header: "Type" },
  { accessorKey: "Revision", header: "Revision" },
  { accessorKey: "State", header: "State" },
  { accessorKey: "Owner", header: "Owner" },
  { accessorKey: "Collabspace", header: "Collabspace" },
];


