import React, { useEffect } from "react";
import { refreshWidgetData } from "./services/api/refreshService"; // Import refresh
import useToast from "./hooks/useToast"; // Import useToast
import useDroppableArea from "./hooks/useDroppableArea"; // Import useDroppableArea
import store from "./store";
import { MSG_REFRESH_ERROR, MSG_REFRESH_SUCCESS } from "./utils/toastMessages";

const WidgetLifecycle = ({ children }) => {
  // Receives children
  const { handleDrop } = useDroppableArea();
  const { showSuccessToast, showErrorToast } = useToast();

  useEffect(() => {
    // onRefresh logic, set up *once* in a useEffect
    if (window.widget) {
      // Make sure we have access to the widget object
      const onRefresh = async () => {
        // Define an async function
        const droppedObjectData =
          store.getState()?.droppedObject?.droppedObjectData;
        const droppedData = droppedObjectData.initialDraggedData;
        console.log("[onRefresh] droppedData:", droppedData);

        if (
          droppedData &&
          droppedData.data.items[0].objectId &&
          droppedData.data.items[0].objectType &&
          typeof handleDrop === "function"
        ) {
          try {
            const dataItems = droppedData.data.items;
            await refreshWidgetData(dataItems, handleDrop); // Use it
            showSuccessToast(MSG_REFRESH_SUCCESS);
          } catch (error) {
            console.error("Error during refresh:", error);
            showErrorToast(MSG_REFRESH_ERROR);
          }
        } else {
          console.error("[onRefresh] initialDraggedData is undefined");
        }
      };

      window.widget.addEvent("onRefresh", onRefresh);

      return () => {
        // Cleanup: Remove the event listener when the component unmounts
        window.widget.removeEvent("onRefresh", onRefresh);
      };
    }
  }, [handleDrop, showSuccessToast, showErrorToast]); // Correct dependencies

  return <>{children}</>; // Render children
};

export default WidgetLifecycle;
